function physics(i, dt){
  const lane = lanes[i], st = state[i];
  const Fs = lane.mus * M * G;   // 最大静摩擦
  const Fk = lane.muk * M * G;   // 滑动摩擦
  let fric;
  if (!st.running || (Math.abs(st.v) < 1e-6 && F() <= Fs)) {
    // 静摩擦：与推力平衡
    fric = Math.min(F(), Fs);
    if (st.running && F() <= Fs){ st.v = 0; st.running = false; if (st.stoppedAt === null) st.stoppedAt = st.x; }
  } else {
    fric = Fk;
    const a = (F() - fric) / M;
    st.v += a * dt;
    if (st.v <= 0 && F() < Fk){ st.v = 0; st.running = false; if (st.stoppedAt === null) st.stoppedAt = st.x; }
    if (st.v > 0) st.running = true;
    st.x += st.v * dt;
    if (st.x * PX_PER_M > XMAX - X0){ st.x = (XMAX - X0) / PX_PER_M; st.v = 0; st.running = false; if (st.stoppedAt === null) st.stoppedAt = st.x; }
  }
  st.peakF = fric;
  return { fric, moving: st.running || Math.abs(st.v) > 0 };
}

/* 用户偏好深色时，仅轻微加深上部背景，仍保持柔和并避免过深；
   底部青绿保持不变，文字对比度不受影响。 */
@media (prefers-color-scheme: dark) {
  .theme-soft-mint {
    --bg-page-top: #22302a;
    --bg-page-upper: #2a3b33;
    --bg-page-upper-deep: #31473d;
    --bg-card: #31473d;
    --bg-card-tint: #354c41;
    --text-primary: #eef5f0;
    --text-secondary: #a8bcb1;
    --border-soft: #3d574b;
  }
}
